function nav(filter=''){let group='';$('#nav').innerHTML=lessons.filter(l=>(l.title+l.intro+l.steps.join('')).toLowerCase().includes(filter.toLowerCase())).map(l=>{let h=l.group!==group?`<small>${esc(l.group)}</small>`:'';group=l.group;return h+`<a href="#${l.id}" class="${lessons[current]===l?'active':''}"><span>${Model.done.includes(l.id)?'✓':String(lessons.indexOf(l)+1).padStart(2,'0')}</span>${l.title}</a>`}).join('')||'<p>沒有符合的課程</p>';$('#progressText').textContent=`已完成 ${Model.done.length} / ${lessons.length} 課程`;$('#progressBar').style.width=Model.done.length/lessons.length*100+'%'}
function render(){let id=location.hash.slice(1)||'start';if(id==='sources'){sources();return}current=Math.max(0,lessons.findIndex(l=>l.id===id));const l=lessons[current];nav($('#search').value);$('#main').innerHTML=`<div class="crumb">學習中心　 /　System Platform　 /　${l.group}</div><div class="eyebrow">LESSON ${String(current+1).padStart(2,'0')} · ${l.group}</div><h1>${l.title}</h1><div class="subtitle">${l.subtitle}</div><div class="meta"><span class="pill">入門實作</span><span>◷ 約 ${l.minutes} 分鐘</span><span>2023 R2 SP1 P03</span></div><section class="intro" id="overview"><b>這一課，你會學到什麼？</b><p>${l.intro}</p></section>${["start","template"].includes(l.id)?physicalIllustration():""}${lessonVisuals(l.id)}<h2 id="steps">逐步操作</h2>${l.steps.map((s,i)=>`<div class="step"><span>${i+1}</span><p>${esc(s)}</p></div>`).join('')}<div class="tip"><b>IT 人的理解方式 / 操作提醒</b><br>${l.tip}</div><h2 id="lab">動手試試看</h2><div class="lab"><div class="lab-head"><span>PLC 通訊與備援互動面板</span><span>● 瀏覽器模擬</span></div><div class="lab-body"><div class="monitor"><div><small>Temperature001.PV</small><strong id="pv">50.0</strong></div><div><small>QUALITY</small><div id="quality"><i class="lamp"></i>C0:Good</div></div><div><small>ACTIVE SOURCE</small><div id="active">Primary</div></div><div><small>LIMIT ALARM</small><div id="alarm">Normal</div></div></div><div class="lab-controls"><label for="range">模擬 PV</label><input type="range" id="range" min="0" max="100" value="50"><button id="switch">切換備援</button><button id="disconnect">模擬斷線</button></div><p class="caption">調高到 75 以上觀察告警，模擬斷線觀察品質。操作不會寫入 PLC。</p></div></div><h2 id="quiz">檢查你的理解</h2><div class="quiz"><b>${l.question}</b>${l.options.map((o,i)=>`<button data-answer="${i}">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}<div class="feedback" aria-live="polite" id="feedback"></div></div><h2 id="trouble">卡住了？先檢查這裡</h2><div class="trouble">${l.trouble}</div><div class="sources"><b>資料依據與版本</b><p>內部：AVEVA_PLC_InTouch_操作步驟教學，第 3–26 頁；AVEVAApplicationServer_2023_RevA_Presentation。AHU 範例為教學設計。<a href="#sources">查看官方來源與版本說明 ↗</a></p></div><div class="bottom">${current?`<a href="#${lessons[current-1].id}">← 上一課</a>`:'<span></span>'}<button class="primary" id="complete">${Model.done.includes(l.id)?'✓ 已完成本課':'標記已完成 ✓'}</button>${current<lessons.length-1?`<a href="#${lessons[current+1].id}">下一課 →</a>`:'<a href="#start">返回起點</a>'}</div>`;
let connected=true,backup=false;const update=()=>{let v=+$('#range').value;$('#pv').textContent=connected?v.toFixed(1):'—';$('#quality').textContent=connected?'● C0:Good':'● 00:Bad';$('#alarm').textContent=!connected?'資料無效':v>=90?'HiHi':v>=75?'Hi':v<=10?'LoLo':v<=25?'Lo':'Normal'};$('#range').oninput=update;$('#switch').onclick=()=>{$('#active').textContent=(backup=!backup)?'Backup':'Primary'};$('#disconnect').onclick=()=>{connected=!connected;$('#disconnect').textContent=connected?'模擬斷線':'恢復連線';update()};document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{$('#feedback').textContent=+b.dataset.answer===l.answer?'✓ 正確！請繼續完成實作並記錄結果。':`再想想：${l.tip}`});$('#complete').onclick=()=>{if(!Model.done.includes(l.id))Model.done.push(l.id);localStorage.setItem('fmcs-done',JSON.stringify(Model.done));$('#complete').textContent='✓ 已完成本課';nav($('#search').value)};$('#sidebar').classList.remove('open');window.scrollTo(0,0)}
