let time=0,over=0,active=false,ack=false,history=[23];
function advanceAlarm(temp,connected,seconds){if(!connected){over=0;return}if(temp>25){over+=seconds;if(over>=30&&!active){active=true;ack=false}}else{over=0;if(temp<24.5)active=false}}
function render(){let t=Number($('temp').value),connected=$('connection').checked;$('reading').textContent=connected?`${t.toFixed(1)}°C`:'資料無效';let status=!connected?'通訊中斷：警報狀態可能過時，請查現場':active?`高溫警報／${ack?'已確認':'未確認'}${t>=24.5?'／條件未恢復':''}`:over>0?`超限累計 ${over} 秒／等待 30 秒發報`:ack?'警報已恢復／已確認':'正常／尚無高溫警報';$('alarmStatus').textContent=status;$('alarmStatus').classList.toggle('alarm',active||!connected);$('simDetail').textContent=`模擬時間 ${time} 秒。資料品質 ${connected?'Good':'Bad'}。確認警報不會降低溫度。`;$('ack').disabled=!active;draw()}
function draw(){let c=$('trend'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.strokeStyle='#98674f';ctx.beginPath();ctx.moveTo(0,160-(25-20)*16);ctx.lineTo(1000,160-(25-20)*16);ctx.stroke();ctx.fillStyle='#c5dcd8';ctx.font='14px sans-serif';ctx.fillText('25°C 高溫門檻',12,70);ctx.strokeStyle='#8edcbb';ctx.lineWidth=3;ctx.beginPath();let pen=false;history.forEach((v,i)=>{if(v===null){pen=false;return}let x=20+i*960/Math.max(1,history.length-1),y=160-(v-20)*16;if(pen)ctx.lineTo(x,y);else ctx.moveTo(x,y);pen=true});ctx.stroke()}
$('advance').onclick=()=>{time+=10;advanceAlarm(Number($('temp').value),$('connection').checked,10);history.push($('connection').checked?Number($('temp').value):null);if(history.length>50)history.shift();render()};$('temp').oninput=()=>{advanceAlarm(Number($('temp').value),$('connection').checked,0);render()};$('connection').onchange=()=>{advanceAlarm(Number($('temp').value),$('connection').checked,0);render()};$('ack').onclick=()=>{if(active)ack=true;render()};$('reset').onclick=()=>{time=0;over=0;active=false;ack=false;history=[23];$('temp').value=23;$('connection').checked=true;render()};document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{$('feedback').textContent=b.dataset.answer==='1'?'答對了。Historian 主要以 History Blocks 保存歷史值，SQL 介面提供查詢。':'再想一下：Galaxy 主要保存專案設定，設備歷史交給 Historian。'});render();

